{
  "name": "SCPI数字万用表",
  "name_en": "SCPI Digital Multimeter",
  "manufacturer": "",
  "description": "通用 SCPI 兼容数字万用表，用于测量电压、电流、电阻等电学量，并支持量程、分辨率、采样和触发参数配置。",
  "description_en": "A generic SCPI-compliant digital multimeter used to measure electrical quantities such as voltage, current, and resistance, with configurable range, resolution, sampling, and triggering settings.",
  "actions": [
    {
      "action_name": "auto-input_range",
      "description": "获取/设置/定义当前测量模式的输入量程。",
      "description_en": "Get/set/define the input range for the current measurement mode."
    },
    {
      "action_name": "auto-measure",
      "description": "执行一次测量。",
      "description_en": "Perform a one-time measurement."
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置/定义测量模式。",
      "description_en": "Get/set/define the measurement mode."
    },
    {
      "action_name": "auto-relative",
      "description": "获取/设置/定义相对测量状态。",
      "description_en": "Get/set/define the relative measurement state."
    },
    {
      "action_name": "auto-resolution",
      "description": "获取/设置/定义测量分辨率。",
      "description_en": "Get/set/define the measurement resolution."
    },
    {
      "action_name": "auto-sample_count",
      "description": "获取/设置/定义每次触发的采样数。",
      "description_en": "Get/set/define the number of samples per trigger."
    },
    {
      "action_name": "auto-sample_source",
      "description": "获取/设置/定义采样源。",
      "description_en": "Get/set/define the sample source."
    },
    {
      "action_name": "auto-sample_timer",
      "description": "获取/设置/定义采样定时间隔。",
      "description_en": "Get/set/define the sample timer interval."
    },
    {
      "action_name": "auto-trigger_count",
      "description": "获取/设置/定义触发计数。",
      "description_en": "Get/set/define the trigger count."
    },
    {
      "action_name": "auto-trigger_delay",
      "description": "获取/设置/定义触发延迟。",
      "description_en": "Get/set/define the trigger delay."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取/设置/定义触发模式。",
      "description_en": "Get/set/define the trigger mode."
    }
  ],
  "tag_hints": [
    "digital multimeter",
    "SCPI control",
    "electrical measurement",
    "voltage current resistance",
    "triggered acquisition",
    "sampling configuration",
    "measurement resolution"
  ]
}

